 "content": "def transform(grid):
    """Combine the two 4-column panels unless their colored shapes overlap;
    in that case retain the left (1) shape."""
    left = [row[:4] for row in grid]
    right = [row[5:9] for row in grid]
    overlap = any(left[r][c] == 1 and right[r][c] == 2
                  for r in range(len(grid)) for c in range(4))
    out = []
    for r in range(len(grid)):
        row = []
        for c in range(4):
            if left[r][c] == 1:
                row.append(1)
            elif not overlap and right[r][c] == 2:
                row.append(2)
            else:
                row.append(0)
        out.append(row)
    return out
